import { ogImage, type SocialImage, type SocialMeta, type SocialMetaContext } from '../SocialMeta.js';
import type { SocialMetaBuilderInterface } from './SocialMetaBuilderInterface.js';

/**
 * Meta of an entity page (game, tournament, ...),
 * with an image generated by ogImageRouter at /og/<imageType>/<imageId>.png
 */
export default abstract class AbstractEntityMetaBuilder<T> implements SocialMetaBuilderInterface<T>
{
    /**
     * Images path, e.g "games" for /og/games/<imageId>.png
     */
    abstract readonly imageType: string;

    /**
     * Id in image url, from which ogImageRouter loads entity.
     */
    abstract imageId(data: T): string;

    /**
     * Changes when image content changes, to refresh crawlers and server caches.
     * Must change for everything displayed on image.
     */
    abstract imageVersion(data: T): string;

    abstract buildMeta(data: T, context: SocialMetaContext): Partial<SocialMeta>;

    protected image(data: T, context: SocialMetaContext, alt: string): SocialImage
    {
        return ogImage(context, `${this.imageType}/${encodeURIComponent(this.imageId(data))}`, this.imageVersion(data), alt);
    }
}
